function cookieReport(line) {
  const [pair, ...rest] = line.split(";").map((part) => part.trim());
  const name = pair.split("=")[0];
  const attrs = rest.map((part) => part.toLowerCase());
  const maxAge = Number(attrs.find((a) => a.startsWith("max-age="))?.slice(8));
  const ok =
    attrs.includes("httponly") &&
    attrs.includes("secure") &&
    (attrs.includes("samesite=lax") || attrs.includes("samesite=strict")) &&
    maxAge >= 1 && maxAge <= 3600;
  return `${name}: ${ok ? "ok" : "FAIL"}`;
}

console.log(cookieReport("access_token=eyJ; Path=/; Max-Age=900; HttpOnly; Secure; SameSite=Lax"));
console.log(cookieReport("_csrf=abc; path=/; httponly; secure; samesite=strict; max-age=3600"));
console.log(cookieReport("sid=1; Path=/; HttpOnly; Secure; SameSite=Lax"));
console.log(cookieReport("sid=1; Max-Age=86400; HttpOnly; Secure; SameSite=Lax"));

