questions.solution:
function checkSecrets(env, names) {
  const problems = [];
  const present = [];
  for (const name of names) {
    const value = env[name];
    if (value === undefined || value === "") problems.push(`${name} is missing`);
    else if (value.length < 32) problems.push(`${name} is shorter than 32 characters`);
    else present.push(value);
  }
  if (new Set(present).size !== present.length) problems.push("secrets must all be different");
  return problems;
}

const good = "k".repeat(40);
console.log(checkSecrets({ JWT_SECRET: "hunter2", CSRF_SECRET: good }, ["JWT_SECRET", "CSRF_SECRET", "API_KEY"]));
