function stringBuiltQueries(source) {
  const pattern = /\.(query|exec)\(\s*`[^`]*\$\{/;
  return source
    .split("\n")
    .map((line, index) => (pattern.test(line) ? index + 1 : 0))
    .filter((lineNumber) => lineNumber > 0);
}

